import java.util.*;
import java.math.*;

public class Main {
    static final double epsilon = 1e-8;
    static final int pattern = 9;
    static final int first_element = 0;
    static final int second_element = 1;

    static long powerMod(long a, long e, long mod) {
        long result = 1;
        long base = a % mod;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            e >>= 1;
        }
        return result;
    }

    static long absValue(long x) {
        return x < 0 ? -x : x;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        long mod = sc.nextLong();

        long[] factorials = new long[N + 1];
        long[] invFactorials = new long[N + 1];

        factorials[0] = 1;
        invFactorials[0] = 1;

        for (int i = 1; i <= N; i++) {
            factorials[i] = (factorials[i - 1] * i) % mod;
            invFactorials[i] = (invFactorials[i - 1] * powerMod(i, mod - 2, mod)) % mod;
        }

        long[] countArr = new long[M + 1];
        long[] sumArr = new long[M + 1];

        Arrays.fill(countArr, 0);
        Arrays.fill(sumArr, 0);

        countArr[0] = 1;

        for (int m = 1; m <= M; m++) {
            for (int k = 0; k < m; k++) {
                long left_c = (countArr[k] * invFactorials[k]) % mod;
                long right_c = (countArr[m - 1 - k] * invFactorials[m - 1 - k]) % mod;
                long left_s = (sumArr[k] * invFactorials[k]) % mod;
                long right_s = (sumArr[m - 1 - k] * invFactorials[m - 1 - k]) % mod;

                countArr[m] = (countArr[m] + left_c * right_c % mod * (m + 1)) % mod;

                long term1 = (left_s * right_s) % mod;
                long term2 = (left_c * right_s) % mod;
                long term3 = (left_s * right_c) % mod;
                long sumPart = (term1 + term2 + term3) % mod;
                sumPart = (sumPart * (m + 1)) % mod;

                long kTermNumerator = k * (k + 1) + (m - k) * (m - k - 1);
                long kTerm = (kTermNumerator / 2) % mod;

                long sumArrAdd = (sumPart + (left_c * right_c % mod) * kTerm % mod) % mod;

                sumArr[m] = (sumArr[m] + sumArrAdd) % mod;
            }
            countArr[m] = (countArr[m] * factorials[m - 1]) % mod;
            sumArr[m] = (sumArr[m] * factorials[m - 1]) % mod;
        }

        long[][] cntAns = new long[N + 1][M + 1];
        long[][] sumAns = new long[N + 1][M + 1];

        for (int i = 0; i <= N; i++) {
            Arrays.fill(cntAns[i], 0);
            Arrays.fill(sumAns[i], 0);
        }

        cntAns[0][0] = 1;

        for (int i = 1; i <= N; i++) {
            int maxJ = Math.min(i, M);
            for (int j = 0; j <= maxJ; j++) {
                cntAns[i][j] = cntAns[i - 1][j];
                sumAns[i][j] = sumAns[i - 1][j];

                if (j == i) {
                    cntAns[i][j] = (cntAns[i][j] + countArr[i] * invFactorials[i]) % mod;
                    sumAns[i][j] = (sumAns[i][j] + sumArr[i] * invFactorials[i]) % mod;
                }

                for (int k = 1; k <= Math.min(j, i - 1); k++) {
                    long c = (countArr[k] * invFactorials[k]) % mod;
                    long s = (sumArr[k] * invFactorials[k]) % mod;

                    cntAns[i][j] = (cntAns[i][j] + cntAns[i - 1 - k][j - k] * c) % mod;
                    sumAns[i][j] = (sumAns[i][j] + (sumAns[i - 1 - k][j - k] * c + cntAns[i - 1 - k][j - k] * s)) % mod;
                }
            }
        }

        long finalResult = (sumAns[N][M] * factorials[M]) % mod;
        System.out.println(finalResult);
        sc.close();
    }
}
